args.sparql:
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?fatherLabel WHERE {
  dbr:Cyril_Holland dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = "en") }
}

PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?father ?fatherLabel ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Cyril_Holland dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = "en") }
  OPTIONAL { ?father dbo:deathPlace ?dp . }
  OPTIONAL { ?father dbp:deathPlace ?dp2 . }
  BIND(COALESCE(?dp, ?dp2) AS ?deathPlace) .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = "en") }
}

